"描述定制嗓音:免选音色——角色配音按项目声纹卡(voice.json 声学字段)自动拼装声线描述,旁白按项目旁白声线卡冻结描述(无卡按工单 --instructions);项目已有冻结 voiceprint 样本时自动作参考锚,同一角色逐句/逐段合成不漂音色。": "Voix personnalisée par description : pas de sélection de voix — le doublage des personnages assemble automatiquement la description depuis la carte d'empreinte vocale du projet (champs acoustiques de voice.json) ; la narration utilise la description gelée de la carte de voix du narrateur (sans carte : --instructions de l'ordre) ; si un échantillon voiceprint gelé existe déjà, il sert automatiquement d'ancre de référence et la voix ne dérive pas en synthèse phrase par phrase/segment par segment.",
