"Agent 高级设置": "Paramètres avancés Agent",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Paramètres avancés des agents : concurrence des agents fan-out, délais d’exécution / sans sortie, quota de mémoire conversationnelle inter-tours, plafond de relances automatiques, délai d’attente de confirmation de relance, profondeur de réflexion",
"重跑等待确认(秒)": "Attente de confirmation de relance (s)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "L’attente de confirmation de relance doit être un entier entre {min} et {max} (secondes)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "Durée d’attente des fenêtres de confirmation de type relance (« Relancer ? », etc.), 60 secondes par défaut : si le compte à rebours s’achève sans réponse, l’option par défaut (généralement « Relancer ») est appliquée automatiquement, le pipeline ne reste donc jamais bloqué à attendre quelqu’un. L’augmenter vous laisse plus de temps pour trancher, au prix d’une attente plus longue sur la fenêtre en l’absence de surveillance ; une attente plus courte demandée explicitement par un agent reste valable, sans jamais pouvoir dépasser cette valeur. Les fenêtres de signature (signature manuelle des portes H) n’ont jamais de compte à rebours et ne se confirment jamais seules : elles ne sont pas concernées. Réglage global ; prend effet pour les confirmations émises après l’enregistrement.",
"⚙️ Agent 高级设置": "⚙️ Paramètres avancés Agent",
"重跑次数": "Nombre de relances",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Plafond de relances / re-rolls automatiques des agents, 0 par défaut : si la notation d’acceptation, la revue QA ou le contrôle machine échoue, le Producteur renvoie automatiquement le travail avec ses remarques ; si la génération vidéo/image échoue au contrôle machine, un re-roll automatique est lancé. Lorsqu’une même tâche atteint ce nombre et échoue encore, elle est escaladée à l’utilisateur au lieu d’être retentée ; 0 désactive totalement les relances automatiques (le premier échec est escaladé). Réglage global, injecté dans tous les agents via le prompt d’exécution et prioritaire sur le « 3 fois maximum » codé en dur dans la documentation ; s’applique aux exécutions lancées après l’enregistrement.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "Le nombre de relances doit être un entier entre 0 et {max} (0 = aucune relance automatique)",
"轮次上限": "Limite de tours",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Plafond de tours de conversation du moteur par ordre de travail, 250 par défaut : ne concerne que les moteurs claude et grok (paramètre headless --max-turns ; sans lui, illimité — cette vanne évite les boucles incontrôlées). Les moteurs codex/pi/opencode n'ont pas ce paramètre et ne sont pas concernés ; deepagents utilise la limite de récursion de son propre framework. Au plafond, le moteur est coupé net sans reprise possible — le reçu n'affiche que le code de sortie 1 ; les artefacts déjà écrits sont conservés mais la vérification et le reçu manquent. Pour les postes à gros volume (sélection par groupe, découpe par lots), un ordre couvrant des dizaines de groupes rend 100 tours très insuffisants ; si le plafond est encore atteint, réduisez d'abord la taille des lots, puis augmentez cette valeur. Réglage global ; s'applique aux exécutions lancées après enregistrement.",
"轮次上限需为 {min}-{max} 的整数": "La limite de tours doit être un entier entre {min} et {max}",
"思考深度": "Profondeur de réflexion",
"引擎默认": "Défaut du moteur",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Réglage unifié de la profondeur de réflexion (Thinking Effort), par défaut « Défaut du moteur » : à l’envoi il est traduit en paramètre d’intensité de raisonnement de chaque moteur — claude → --effort, codex → model_reasoning_effort (pas de max ; xhigh utilisé), pi → --thinking, opencode → --variant (ignoré si le modèle n’a pas ce niveau), grok → --reasoning-effort (pas de max ; ramené à xhigh), deepagents → reasoning_effort (canaux cloud/OpenRouter uniquement ; non envoyé aux modèles locaux) ; la CLI kimi n’a pas de paramètre équivalent et n’est pas concernée. Plus profond = plus stable mais plus lent et plus coûteux en tokens ; « Défaut du moteur » ne transmet rien et conserve la configuration propre de chaque moteur (ex. effortLevel dans ~/.claude/settings.json, model_reasoning_effort dans ~/.codex/config.toml). Réglage global pour tous les agents, effectif pour les exécutions lancées après l’enregistrement.",
