"Seedance 2.5(最新,单段30秒直出,参考上限30图+10视频+10音频,480p/720p)": "Seedance 2.5 (le plus récent, vidéo de 30 secondes en une seule génération, jusqu'à 30 images + 10 vidéos + 10 audios de référence, 480p/720p)",
"Seedance 2.0(音画同生,多模态生视频,最高4K)": "Seedance 2.0 (audio et vidéo simultanés, génération vidéo multimodale, jusqu'à 4K)",
"对话记忆": "Mémoire conversationnelle",
"对话记忆额度(KB,默认 16):创作型 Agent 每次运行接续上次会话,多轮对话有连续记忆;单个会话历史超过该额度自动新开会话防膨胀(扇出型无状态 Agent 本就每单全新会话,不受此项影响)。调大可保留更长的连续记忆,但 resume 每轮重发全部历史,越大越慢、token 消耗越高。拖到 0 即完全关闭:所有 Agent(含总制片)每次运行/发言都是全新会话,跨工单信息只靠落盘产物(bible、工单档案等)传递,可显著省 token,但对话上下文不再延续。全局设置,保存后立即对后续运行生效;调小或关闭期间会话号照常回存,重新调大后从最近一次会话继续。": "Quota de mémoire conversationnelle (KB, 16 par défaut) : les Agents créatifs reprennent leur session précédente à chaque exécution, les conversations multi-tours gardent donc une mémoire continue ; dès que l'historique d'une session dépasse ce quota, une nouvelle session est ouverte automatiquement pour éviter le gonflement (les Agents fan-out sans état repartent de toute façon d'une session neuve à chaque ticket et ne sont pas concernés). Un quota plus grand conserve une mémoire continue plus longue, mais resume renvoie tout l'historique à chaque tour — plus il est grand, plus c'est lent et coûteux en tokens. Glisser à 0 désactive complètement : chaque Agent — Producteur inclus — repart d'une session neuve à chaque exécution/message, et les informations inter-tickets ne passent que par les artefacts sur disque (bible, dossiers de tickets, etc.), ce qui économise beaucoup de tokens mais rompt la continuité conversationnelle. Réglage global ; prend effet immédiatement pour les exécutions suivantes. Les ID de session restent enregistrés même quota réduit ou à 0 : en le remontant, on reprend depuis la session la plus récente.",
"✓ 会话恢复生效中:单会话超过 {kb} KB 自动新开": "✓ Reprise de session active : une session dépassant {kb} KB redémarre automatiquement",
"对话记忆需为 0-{max} 的整数(KB,0=关闭)": "La mémoire conversationnelle doit être un entier entre 0 et {max} (KB, 0 = désactivée)",
"已关闭:每次运行全新会话": "Désactivée : session neuve à chaque exécution",
"跨 Agent 并发额度": "Quota de concurrence inter-Agents",
"全局同时运行的工单(工人进程)总上限,默认 8,最高 50:所有 Agent 的运行共用这一池进程槽,占满后新工单排队等槽;总制片等调度型 Agent 大部分时间静默等子任务,不占槽。它同时是下方「单 Agent 并发额度」的取值上限。每个槽 = 一个真实的模型 CLI 进程,调大会同步放大 token 消耗速度、本机负载与网络代理并发压力,建议按机器与额度承受力逐步上调。保存后立即对后续启动的工单生效。": "Plafond global de tickets (processus de travail) exécutés simultanément ; 8 par défaut, 50 au maximum. Les exécutions de tous les Agents partagent ce seul pool de créneaux de processus ; une fois plein, les nouveaux tickets attendent un créneau. Les Agents coordinateurs comme le producteur exécutif attendent surtout leurs sous-tâches et n'occupent pas de créneau. C'est aussi la borne supérieure du « Quota de concurrence par Agent » ci-dessous. Chaque créneau = un vrai processus CLI du modèle : augmenter la valeur amplifie d'autant la consommation de tokens, la charge locale et la pression de concurrence sur le proxy — augmentez progressivement selon ce que supportent votre machine et votre quota. S'applique aux exécutions lancées après l'enregistrement.",
"跨 Agent 并发额度需为 1-{max} 的整数": "Le quota de concurrence inter-Agents doit être un entier entre 1 et {max}",
"单 Agent 并发额度": "Quota de concurrence par Agent",
"扇出型 Agent(场景资产、视频生成、审核、验收评分等按场景/组一单的工位)同一 Agent 可同时运行的工单数上限,默认 5,最大不超过上方「跨 Agent 并发额度」。创作型 Agent 为保护会话连续性恒为串行,不受此值影响;全部运行仍受跨 Agent 并发额度总闸。每个并发 = 一个真实的模型 CLI 进程,调大会成倍加快额度消耗,网络代理高并发下也更易断连,建议逐步上调。": "Plafond de tickets qu'un même Agent de type fan-out (postes traitant un ticket par scène/groupe : décors, génération vidéo, contrôle, notation de recette) peut exécuter simultanément ; 5 par défaut, sans dépasser le « Quota de concurrence inter-Agents » ci-dessus. Les Agents créatifs restent toujours en série pour préserver la continuité de session et ne sont pas concernés ; toutes les exécutions passent encore par la porte de concurrence inter-Agents. Chaque concurrence = un vrai processus CLI du modèle : augmenter la valeur accélère d'autant la consommation de quota et multiplie les coupures de proxy en forte concurrence — augmentez progressivement.",
"运行超时(分钟)": "Délai d’exécution (min)",
"无输出超时(分钟)": "Délai sans sortie (min)",
"运行超时:单个工单从启动算起的墙钟上限,默认 120 分钟(总制片要等整条流水线,自动放宽 4 倍),到点连同派生子进程一起终止并记为出错,是回收挂死进程的最后防线。无输出超时:引擎连续多长时间没有任何事件输出即判定挂死并终止,默认 30 分钟,填 0 关闭;比墙钟更早识别 API 长连接不返回、代理断流等假死,又不会误伤跑得慢但在正常干活的长批量任务(总制片大部分时间静默等子任务,不受此项约束)。注意单次工具调用期间引擎不会有事件输出,该值须大于工单里最长的一次工具调用。均为全局设置,保存后对后续启动的工单生效。": "Délai d’exécution : plafond horloge murale d’un ticket depuis son lancement, 120 minutes par défaut (le Producteur attend toute la chaîne et obtient automatiquement 4×) ; à échéance, l’exécution et ses processus enfants sont arrêtés et marqués en erreur — dernier rempart pour récupérer les processus bloqués. Délai sans sortie : durée maximale sans aucun événement émis par le moteur avant qu’il soit jugé bloqué et arrêté, 30 minutes par défaut, 0 désactive ; détecte les blocages (connexions API longues qui ne reviennent jamais, coupures de proxy) bien plus tôt que l’horloge murale sans pénaliser les longs lots lents mais sains (le Producteur attend silencieusement ses sous-tâches la plupart du temps et en est exempté). Attention : pendant un appel d’outil, le moteur n’émet aucun événement ; la valeur doit donc dépasser le plus long appel d’outil du ticket. Réglages globaux, appliqués aux exécutions lancées après l’enregistrement.",
"运行超时需为 {min}-{max} 的整数(分钟)": "Le délai d’exécution doit être un entier entre {min} et {max} (minutes)",
"无输出超时需为 0-{max} 的整数(分钟,0=关闭)": "Le délai sans sortie doit être un entier entre 0 et {max} (minutes, 0 = désactivé)",
"并发额度需为 1-{max} 的整数": "Le quota de concurrence doit être un entier entre 1 et {max}",
