",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", jointes au message à chaque réveil du Producteur par l'exécution automatique, elles survivent donc à la réouverture de session ; idéales pour des contraintes de long terme, à formuler de préférence sous forme conditionnelle (ex. 「tant que les scénarios ep01-ep10 ne sont pas tous terminés, ne pas assigner de bons de travail de type conception」) ; laisser vide pour ne rien joindre",
