"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Temps d'inactivité : inspection à chaque intervalle de cette durée ; le message de contrôle d'état n'est envoyé que si la pipeline est inactive (aucune tâche en cours, rien en attente de confirmation), 5 minutes par défaut. Seuil : si l'usage de session sur la fenêtre de 5 heures du moteur actif du Producer (claude/codex) atteint cette valeur, l'envoi est suspendu pour ce cycle ; si l'usage est illisible, l'envoi est autorisé. Réglages globaux s'appliquant à tous les projets (l'interrupteur, bouton 🤖 du panneau d'exécution, est indépendant par projet)",
