"绑定后,你在手机端发的消息会作为给总制片的指令进入当前项目的对话,与在控制台输入完全等效。": "Une fois lié, les messages envoyés depuis votre téléphone entrent dans la conversation du projet courant comme instructions au Producer, exactement comme si vous les tapiez dans la console.",
