"Voice Design 模型按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用),Voice Clone 模型按嗓音样本 + 对白文字生成对白": "Le modèle Voice Design génère un échantillon de voix à partir d'une description textuelle de la voix du personnage (lors de la conception de la voix) ; le modèle Voice Clone génère le dialogue à partir d'un échantillon de voix et du texte du dialogue",
"Voice Clone API": "API Voice Clone",
"Voice Design API": "API Voice Design",
"Voice Design:按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用);Voice Clone:按嗓音样本 + 对白文字生成对白。两者按用途自动选择;未配置 Voice Design 时一律走 Voice Clone": "Voice Design : génère un échantillon de voix à partir d'une description textuelle de la voix du personnage (lors de la conception de la voix). Voice Clone : génère le dialogue à partir d'un échantillon de voix et du texte du dialogue. Le choix est automatique selon l'usage ; sans Voice Design configuré, tout passe par Voice Clone",
