"获取;工作流须先在网页端跑通,并把 {{PROMPT}} 等占位符写入对应节点输入位(约定与本地工作流一致),再把工作流 ID 或页面链接粘贴到「添加工作流」验证;国内站与国际站账号与 Key 不互通": "; le workflow doit d'abord s'exécuter avec succès dans l'interface web, avec {{PROMPT}} et les autres placeholders inscrits dans les emplacements d'entrée des nœuds correspondants (même convention que pour les workflows locaux) ; collez ensuite l'ID du workflow ou le lien de la page dans « Ajouter un workflow » pour vérifier ; les comptes et les Keys du site chinois et du site international ne sont pas interchangeables",
