"待提交问题": "Problèmes à soumettre",
"🐞 待提交问题": "🐞 Problèmes à soumettre",
"待提交问题:Agent 运行中发现系统代码缺陷或需要新增功能时自动整理成 issue,点击查看并提交给开发者,让你的客户端运行得更好": "Problèmes à soumettre : lorsqu'un agent détecte en cours d'exécution un défaut du code de l'application ou une fonctionnalité manquante, il le rédige automatiquement en issue ; cliquez pour vérifier et soumettre aux développeurs afin que votre client fonctionne mieux",
"Agent 运行中确认问题属于系统代码缺陷、或需要系统新增功能时,自动整理成 issue 列在下方,点「提交」即打开预填好的 GitHub 页面由你确认提交。": "Lorsqu'un agent confirme en cours d'exécution qu'un problème relève d'un défaut du code de l'application, ou que l'application a besoin d'une nouvelle fonctionnalité, il le rédige automatiquement en issue listée ci-dessous ; « Soumettre » ouvre une page GitHub préremplie que vous confirmez.",
"问题只写机制,内容已脱敏(路径、项目名、密钥),不含剧情、提示词与项目内容。": "Les issues ne décrivent que les mécanismes ; le contenu a été nettoyé (chemins, noms de projet, clés) et ne contient ni intrigue, ni prompts, ni contenu du projet.",
