"虚拟人像资产库 — Agentics：VideoAgents": "Bibliothèque de portraits virtuels — Agentics : VideoAgents",
"火山方舟私域虚拟人像素材库:人物形象图入库后,生成视频时自动以资产 URI 提交,规避人脸参考图审核拦截": "Bibliothèque privée de portraits virtuels Volcano Ark : une fois l'image du personnage enregistrée, la génération vidéo la soumet automatiquement en URI d'actif, évitant les blocages de modération des références de visage",
"🧑‍🎨 虚拟人像资产库": "🧑‍🎨 Bibliothèque de portraits virtuels",
"火山方舟私域素材库:入库的人物形象图在生成视频时以资产 URI 提交,规避人脸参考图审核拦截": "Bibliothèque privée Volcano Ark : les images enregistrées sont soumises en URI d'actif lors de la génération vidéo, évitant les blocages de modération des visages",
"📋 使用前准备": "📋 Préparatifs",
"在火山方舟开通": "Activez sur Volcano Ark le",
"高级创作权益包": "pack Création avancée",
"(私域虚拟人像素材库的前置条件)。": "(prérequis de la bibliothèque privée de portraits virtuels).",
"在火山引擎控制台": "Dans la console Volcano Engine, ouvrez",
"API 访问密钥管理": "Gestion des clés d'accès API",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "créez et récupérez une Access Key / Secret Key (identifiants IAM, pas une clé API Ark préfixée ark-), saisissez-les ci-dessous et enregistrez.",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Après avoir cliqué sur « Activer », gérez les actifs enregistrés ci-dessous ; chaque image de l'aperçu des personnages reçoit un bouton « Enregistrer », et lors de la régénération d'un groupe les références enregistrées (Active) sont soumises automatiquement en URI d'actif (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Remarque : l'enregistrement est examiné de façon asynchrone (Processing → Active/Failed) ; seuls les actifs Active sont utilisables pour la génération vidéo. Les actifs sont isolés par projet Ark — le ProjectName ci-dessous doit correspondre au projet de la clé API Ark utilisée sur la page Modèles de génération (défaut : default).",
"🔑 密钥与开关": "🔑 Identifiants et activation",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "Si Access Key / Secret Key restent vides, les AK/SK configurés dans ⚙️ Réglages → Hébergement de fichiers → Volcano TOS (ou les variables TOS_ACCESS_KEY/TOS_SECRET_KEY) sont utilisés automatiquement.",
"default(须与视频生成 API Key 所属项目一致)": "default (doit correspondre au projet de la clé API de génération vidéo)",
