"镜头分割时,上一个切点后此时长内的切换会被合并;快切素材建议调小。改后点「✂ 重新分割」生效(默认 0.5)": "Lors du découpage, les coupes survenant dans ce délai après la coupe précédente sont fusionnées ; réduisez-le pour des plans rapides. Cliquez sur « ✂ Redécouper » pour appliquer (défaut 0.5)",
