"导演模式:保留最近多少段提示词作为上下文(1–50,默认 12)": "Mode réalisateur : nombre de prompts de segments récents conservés comme contexte (1–50, 12 par défaut)",
"MiniMax H3 Max Director(导演模式专用,实时 WebRTC)": "MiniMax H3 Max Director (mode réalisateur uniquement, WebRTC temps réel)",
"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "Le mode réalisateur est facturé à la seconde (60 s minimum) ; une session est limitée à 2 min par défaut (au-delà, demande à fal) ; fermer la page y met fin",
"导演模式:fal 侧按约 10 秒一块连续生成,单段时长/待播上限/最多段数不适用": "Mode réalisateur : fal génère en continu par blocs d'environ 10 s ; durée de clip / plafond non lu / nombre max de clips sans effet",
"导演模式:MiniMax H3 Max Director 实时连续生成,视频经 WebRTC 直推本页,自带前文记忆不需尾帧衔接;参考图只取第 1 张作首帧;分辨率 480p/768p": "Mode réalisateur : MiniMax H3 Max Director génère en continu en temps réel, la vidéo arrive sur cette page via WebRTC, la mémoire intégrée remplace le raccord par dernière image ; seule la référence n° 1 sert de première image ; résolution 480p/768p",
