"跳到最新一段": "Aller au dernier clip",
"⏭ 最新": "⏭ Dernier",
"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Lecture : les clips générés sont lus dans l'ordre ; tant que le suivant n'est pas prêt, le dernier est rejoué, puis le nouveau est ajouté après la fin du clip courant sans l'interrompre. La génération est souvent plus lente que la lecture, la rediffusion est donc normale ; des clips plus longs réduisent sa part. Quand la limite de clips en attente est atteinte (3 par défaut, réglable dans Options avancées), la génération se met en pause et reprend dès qu'un clip est lu. Après l'arrêt, tous les clips tournent en boucle.",
