// 稀疏悬空预检(2026-10-05):悬空高视点且白模全景里体块太少的位置,出图前先弹窗确认
"这个位置是悬空高视点(镜头离地约 {height} m),白模全景里地面以上的体块只占 {blocks}%(低于 {limit}%)。\n这样的全景多半会被图像模型出成航拍广角照片、被投影机检拒收,白花一次出图费用;主体在全景里只占很小一块,重投影成分镜背景图也会糊。\n\n建议取消后把位置挪近 / 放低再创建。仍要按这个位置出图?": "Cette position est un point de vue en plein air (objectif à environ {height} m au-dessus du sol), et les blocs au-dessus du sol ne couvrent que {blocks}% du panorama du modèle de blocs (moins de {limit}%).\nLe modèle d’image transformera très probablement un tel panorama en photo aérienne grand angle, rejetée par le contrôle de projection — une génération gaspillée ; le sujet n’occupe en outre qu’une petite zone du panorama, si bien que les arrière-plans de plan reprojetés seront flous.\n\nMieux vaut annuler et le créer plus près / plus bas. Générer quand même à cette position ?",
