"语音输入": "Saisie vocale",
"语音输入:开启后控制台与预览页「修改」浮窗的输入框出现麦克风按钮,录音由本机 faster-whisper 转成文字,音频不出本机": "Saisie vocale : une fois activée, un bouton micro apparaît dans la zone de saisie de la console et dans la fenêtre « Modifier » des pages d’aperçu ; les enregistrements sont transcrits localement par faster-whisper et ne quittent jamais cette machine",
"🎤 语音输入": "🎤 Saisie vocale",
"启用语音输入": "Activer la saisie vocale",
"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "Une fois activée, un bouton micro apparaît à droite de la zone de saisie de la console et de la fenêtre « Modifier » des pages d’aperçu : un clic démarre l’enregistrement, un second l’arrête ; l’enregistrement est transcrit par le modèle local faster-whisper et inséré au curseur (60 s max, l’audio ne quitte pas cette machine, aucune clé API requise). La langue de reconnaissance suit celle de l’interface. Le modèle doit être téléchargé avant la première utilisation ; plus il est gros, plus il est précis mais lent : small suffit pour commencer, medium ou large-v3-turbo sur puce Apple.",
