"✓ 模型已就绪,可直接使用": "✓ Modèle prêt à l’emploi",
"模型下载中,可关闭本窗口,下载在后台继续": "Téléchargement du modèle en cours ; vous pouvez fermer cette fenêtre, il continue en arrière-plan",
