"出成片 = 各组当前版本归一化拼正片(cut_post)→ 转场重渲(render_transitions)→ 终版封装(finalize_episode assemble,含片头平移与 intro_offset_ok 机检)→ 后期机检。全部宿主 CLI,几分钟量级。": "Rendre le final = normaliser la version actuelle de chaque groupe et assembler le montage (cut_post) → re-rendre les transitions (render_transitions) → empaquetage final (finalize_episode assemble, avec décalage du générique et contrôle intro_offset_ok) → contrôle post-prod. Tout en CLI hôte, quelques minutes.",
