"环境声保留 dB": "Ambiance conservée (dB)",
"用本机人声分离模型把对白 / 人声从原生声轨里去掉,保留音效、环境声和配乐;画面不重编码。人声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Utilise un modèle local de séparation de voix pour retirer les dialogues / voix de la piste audio d'origine en conservant bruitages, ambiance et musique ; l'image n'est pas réencodée. Voix conservée -60 = supprimée entièrement, plus haut = seulement atténuée. Le modèle (environ 64 Mo) est téléchargé à la première utilisation ; après soumission, il faut relancer le mixage pour que le changement arrive dans le montage final",
"只留人声:用本机人声分离模型把音效、环境声和配乐从原生声轨里去掉;画面不重编码。环境声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Voix seules : utilise un modèle local de séparation de voix pour retirer bruitages, ambiance et musique de la piste audio d'origine ; l'image n'est pas réencodée. Ambiance conservée -60 = supprimée entièrement, plus haut = seulement atténuée. Le modèle (environ 64 Mo) est téléchargé à la première utilisation ; après soumission, il faut relancer le mixage pour que le changement arrive dans le montage final",
