// 分镜剪辑·插黑 / 定格(2026-09-17)
"插黑 / 定格": "Noir / arrêt",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Supprime les plages marquées et enchaîne le reste dans l'ordre en une nouvelle version de ce groupe (durée réduite ; à la finalisation, la piste audio externe et les sous-titres sont resynchronisés via la carte temporelle)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场调整(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Contrôle du rythme : insérer « arrêt sur l'image précédente + noir » à la tête de lecture pour créer une nouvelle version, ou le placer sur la frontière au début / à la fin de ce groupe comme ajustement de transition entre groupes (la soumission l'écrit dans shot_list ; les images sont insérées à la finalisation). L'épisode s'allonge d'autant ; l'audio externe et les sous-titres se décalent via la même carte temporelle ; le son sous le noir peut se prolonger, s'estomper ou se couper",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Montage des plans, quatre modules : ① Supprimer — retirer les plages marquées, le reste devient une nouvelle version ; ② Remplacer — échanger les plages coupées contre les mêmes plages d'une autre version ; ③ Noir / arrêt — insérer arrêt sur image + noir à la tête de lecture ou sur une frontière de groupe pour contrôler le rythme ; ④ Envoyer au monteur — envoyer une consigne à l'agent monteur, le résultat est enregistré comme nouvelle version",
