"高斯模糊与原片按强度混合,压掉高频细节而不糊轮廓(回忆/梦境段的柔焦感);半径随画面高度等比缩放": "Mélange un flou gaussien avec l'original selon l'intensité, atténuant les détails fins sans baver les contours (effet flou doux pour les flashbacks / rêves) ; le rayon suit la hauteur de l'image",
"全部集": "Tous les épisodes",
"按集过滤:只显示该集出现的资产": "Filtrer par épisode : n'afficher que les ressources qui y apparaissent",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式、多集并行": "Paramètres avancés des agents : concurrence des agents fan-out, délais d’exécution / sans sortie, quota de mémoire conversationnelle inter-tours, plafond de relances automatiques, délai d’attente de confirmation de relance, profondeur de réflexion, auto-vérification whitebox, mode Debug, épisodes en parallèle",
"白模自检": "Auto-vérification whitebox",
"多集并行": "Épisodes en parallèle",
"多集同时推进(关闭时一集做完再做下一集)": "Faire avancer plusieurs épisodes à la fois (désactivé : terminer un épisode avant de commencer le suivant)",
"默认关:总制片按集顺序推进,同一时刻只做一集——当前集的全部节点(含该集各签字点,发布环节不计)结束后才开始下一集,剧本、分镜、出图、视频、后期都等前一集做完;集内各组/镜/场景照常并行扇出,速度由上方并发额度决定。当前集停在签字点、被暂缓或有阻塞时,后续集不会开始,开启自动运行时会提醒你。勾选后恢复试点集策略:首集全流程过 H4 签字后,后续各集可同时推进,吞吐更高,但 token 消耗、同时运行的进程与待你审看的内容会成倍增加。不带集号的项目级任务不受影响。全局设置,通过运行提示词注入总制片,自动运行巡检同口径,保存后对后续启动的运行生效。": "Désactivé par défaut : le Producteur exécutif fait avancer les épisodes dans l'ordre et ne travaille que sur un épisode à la fois — l'épisode suivant ne commence qu'une fois tous les nœuds de l'épisode en cours terminés (y compris ses points de validation ; publication exclue), donc script, storyboard, images, vidéo et post-production attendent l'épisode précédent ; à l'intérieur de l'épisode, groupes / plans / scènes sont toujours répartis en parallèle, au rythme fixé par les limites de concurrence ci-dessus. Si l'épisode en cours s'arrête à un point de validation, est mis en attente ou bloqué, les épisodes suivants ne démarrent pas, et l'Auto-run vous le rappelle s'il est activé. Cochez pour revenir à la stratégie de l'épisode pilote : une fois que le premier épisode a parcouru toute la chaîne et a été validé en H4, les épisodes suivants peuvent avancer simultanément — débit plus élevé, mais consommation de tokens, processus simultanés et volume en attente de votre revue se multiplient. Les tâches de niveau projet sans numéro d'épisode ne sont pas concernées. Réglage global, injecté dans le Producteur exécutif via le prompt d'exécution et appliqué de la même façon par les contrôles d'Auto-run ; s'applique aux exécutions lancées après l'enregistrement.",
"显示 SOUL.md 等开发者入口": "Afficher les entrées développeur comme SOUL.md",
"白模调度编译后出静帧自检取景": "Générer des images fixes après compilation du whitebox pour auto-vérifier le cadrage",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "Coché par défaut : chaque fois que l'agent de mise en scène whitebox crée ou modifie un whitebox de storyboard et que la compilation réussit, il exécute la commande hôte render_whitebox.py --stills sur les groupes modifiés dans cet ordre de travail. Le rendu est sans interface : pour chaque plan, des vues caméra au début / milieu / fin (et autres moments clés) plus une vue spatiale, assemblées en une planche-contact par groupe (dans le dossier whitebox/stills de l'épisode sous directing du projet). L'agent lit la planche pour vérifier que le sujet est dans le cadre, qu'aucun mur ou accessoire ne le masque, que face / dos correspondent à la mise en scène et que la valeur de plan convient ; il corrige lui-même les problèmes ou ouvre un point en attente avant de vous passer la main pour relecture et signature dans la page d'aperçu. Le rendu est entièrement local : aucun modèle génératif n'est appelé, aucun coût, et camera.mp4 n'est pas exporté (l'export exige toujours la signature H3W) ; chaque groupe coûte une dizaine de secondes supplémentaires et les tokens d'une lecture d'image. Décoché : seules les auto-vérifications numériques et les contrôles de l'hôte sont effectués, sans images fixes. Réglage global, injecté dans l'agent de mise en scène whitebox via le prompt d'exécution ; s'applique aux ordres lancés après l'enregistrement.",
"本组尚未白模调度，当前没有可审看的白模。": "Ce groupe n'a pas encore fait l'objet d'une mise en scène whitebox ; il n'y a pas de whitebox à examiner.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "La whitebox officielle s'affichera ici une fois que l'agent de mise en scène whitebox aura terminé l'ordre de cet épisode ; inutile d'envoyer des corrections de whitebox d'ici là.",
