"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync (hébergé sur Fal ; synchronisation labiale : 1 image de personnage + 1 audio de 5–14,8 s, sans prompt, durée calée sur l'audio, 480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync : chaque clip utilise la référence n° 1 comme image du personnage (pas de dérive, mais des sauts entre clips) ; le format suit l'image",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync : le 1er tour utilise la référence n° 1 comme image du personnage, les suivants la dernière image du clip précédent (avec « Sans liaison », toujours la référence n° 1) ; le format suit l'image",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "Le modèle de synchro labiale nécessite au moins 1 image de référence (la n° 1 sert d'image du personnage)",
"💬 台词": "💬 Texte à dire",
"人物要说的话;按句分段,逐段语音合成后驱动口型": "Ce que dit le personnage ; découpé par phrases, chaque segment est synthétisé en voix puis pilote les lèvres",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "ex. : Bonjour à tous, bienvenue sur mon live ! Aujourd'hui, j'aimerais vous parler d'un livre que je lis en ce moment.",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "La voix est synthétisée avec la configuration TTS actuelle et la voix par défaut de la page « Modèles de génération » ({tts}). Le flux ne s'arrête pas à la fin du texte, il attend une mise à jour : le texte ajouté à la suite est dit ensuite, un texte réécrit reprend depuis le début.",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "Synchro labiale : le texte est regroupé par phrases en segments d'environ cette durée ({lo}–{hi} s) ; chaque clip dure autant que sa voix (complété par du silence en dessous de 5 s)",
