"分镜剪辑,三个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Montage des plans, trois modules : ① Supprimer — retirer les plages marquées, le reste devient une nouvelle version ; ② Remplacer — échanger les plages coupées contre les mêmes plages d'une autre version de ce groupe ; ③ Envoyer au monteur — envoyer une consigne à l'agent monteur, le résultat est enregistré comme nouvelle version",
