"导入本组另一版本作替换源,A 上标出的时间段换成替换源同一时间段的画面,其余保留,拼成新版本(时长不变)": "Importe une autre version de ce groupe comme source de remplacement : les plages marquées sur A sont remplacées par les mêmes plages de cette source, le reste est conservé et une nouvelle version est assemblée (durée inchangée)",
"用一句话把剪辑要求发给剪辑师工位(10-editing/edit);可附上标好的时间段供指令引用,剪辑师产物会登记为本组新版本": "Envoyez votre demande de montage en une phrase au poste monteur (10-editing/edit) ; vous pouvez joindre les plages marquées pour que la consigne s'y réfère, et le résultat du monteur est enregistré comme nouvelle version de ce groupe",
"删 {n} 段 · -{s}s → 剩 {r}s": "Supprimer {n} plage(s) · -{s}s → {r}s restants",
"要删除的时间段(A 的时间线)": "Plages à supprimer (timeline de A)",
