"没有时间段也能派单;要让剪辑师精确到秒,先在走带条上「标记时间段」": "Vous pouvez envoyer la demande sans plage ; pour donner au monteur des secondes précises, utilisez d'abord « Marquer la plage » sur la barre du moniteur",
