"给剪辑师的指令,例如:第 1 段太拖,砍到 1.5 秒;结尾定格 0.5 秒后再切": "Consigne pour le monteur, par exemple : la plage 1 traîne, ramenez-la à 1,5 s ; arrêt sur image de 0,5 s à la fin avant la coupe",
