"分镜背景图 {ep}/{sid}({role};文件 {file};库 key {key};修订命令 python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<英文修改要求>\":以当前图为参考按意见新出一张并替换本镜该背景图,原图不动)": "Fond du plan {ep}/{sid} ({role} ; fichier {file} ; clé {key} ; commande de révision python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<modification en anglais>\" : génère une nouvelle image à partir de l’actuelle selon la remarque et la substitue pour ce plan ; l’original reste intact)",
"对这张分镜背景图提修改意见,发给修改师处理:以这张图为参考按意见新出一张替换本镜背景图,原图不动": "Envoyer une remarque sur ce fond au réviseur : une nouvelle image est générée à partir de celle-ci selon la remarque et substituée pour ce plan ; l’original reste intact",
"九宫格补图": "complément de grille 3×3",
"🔁 换分镜背景图 —": "🔁 Remplacer le fond de plan —",
"从本场景的背景图库里点选一张(双击看大图),确认后替换本镜这张背景图:改写集索引 directing/<ep>/shot_plates.json 并同步本组 prompt 的参考图;随本组重出生效,非强制重出不会被自动改回": "Choisissez une image dans la bibliothèque de fonds de cette scène (double-clic pour agrandir) ; à la confirmation elle remplace le fond de ce plan : l'index directing/<ep>/shot_plates.json est réécrit et les références du prompt du groupe sont synchronisées. Prend effet à la régénération du groupe ; une régénération non forcée ne le rétablit pas",
