// 生成模型设置·超分板块 + 成片发布页组 clip 方法标签(2026-09-23,models.html / preview_videos.html)
"图像 / 视频 / 数字人 / 超分 / 音乐 / TTS旁白 / 世界模型 生成渠道与模型": "Fournisseurs et modèles : image / vidéo / humain numérique / upscale / musique / narration TTS / modèle de monde",
"🔍 超分": "🔍 Upscale",
"生效渠道=当前选中的标签页(✅),不再跟随视频渠道,保存后生效": "Fournisseur actif = onglet sélectionné (✅), ne suit plus le fournisseur vidéo ; effectif après enregistrement",
"缩放算法": "Filtre de mise à l'échelle",
"lanczos(默认,较锐利)": "lanczos (par défaut, plus net)",
"bicubic(平滑)": "bicubic (lisse)",
"bilinear(最软)": "bilinear (le plus doux)",
"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51 ; plus bas = meilleure qualité et fichier plus gros ; 18 ≈ sans perte visible",
"编码预设": "Préréglage d'encodage",
"slow(默认)": "slow (par défaut)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "Interpolation intégrée sans IA : filtre scale de ffmpeg + réencodage libx264, audio copié tel quel, fps/durée/format inchangés. Aucun nouveau détail, seulement plus de pixels ; sans coût de génération, adapté aux projets qui doivent seulement respecter la spécification de publication. La taille cible est calculée depuis la résolution de livraison × format des paramètres de sortie.",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Mode Draft de Seedance 2.5 : activé dès que cet onglet est sélectionné ; aucune clé ni modèle supplémentaire, les identifiants et le modèle viennent de l'onglet Volcano Engine de la génération vidéo.",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "Conditions : le fournisseur vidéo actif est Volcano Engine (ou BytePlus, même API Ark) avec un modèle Seedance 2.5, et les paramètres de sortie du projet utilisent 480p en brouillon et 1080p en livraison (officiel : brouillon 480p uniquement, final 1080p uniquement). Sinon la vidéo est générée normalement et le journal l'indique.",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "Fonctionnement : ① la génération envoie draft=true et produit un brouillon 480p (même consommation qu'un 480p normal) ; l'id de tâche draft est écrit dans le bloc draft_task du meta.json du clip ; ② l'upscale via genmedia.py upscale demande à Ark le final 1080p à partir de cet id en réutilisant prompt/médias/durée/format/seed/audio (facturation normale), les éléments clés restent identiques au brouillon validé ; ③ l'id est valable 7 jours après création ; ensuite il faut régénérer le brouillon.",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "Conditions (le clip source doit être une sortie native MiniMax-H3 768P) : piste audio présente ; 24 fps ; largeur et hauteur divisibles par 32 ; surface ≤ 768×1344 ; 107–362 images (environ 4–15 s).",
"云端超分工作流": "Workflow d'upscale cloud",
"超分工作流 API": "API du workflow d'upscale",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "(abonnement Comfy Cloud requis, crédits mensuels partagés avec la version web ; l'offre gratuite n'a pas d'accès API) ; la liste des workflows est la même qu'en local (modèles comfy/scale-* ; les nœuds SeedVR2 sont intégrés à ComfyUI officiel et disponibles dans le cloud) ; les clips longs en 1080p ou plus peuvent manquer de VRAM dans le cloud, se fier au résultat de la tâche",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "; faites d'abord tourner un workflow d'upscale de type SeedVR2 dans l'espace de travail, puis collez son ID ou l'URL de la page dans « Ajouter un workflow » pour vérifier ; pour un export sans espaces réservés, le système lie l'unique nœud de chargement vidéo (famille LoadVideo) + le nœud de redimensionnement en amont de SeedVR2Preprocess (côté / largeur-hauteur cibles) + la seed du sampler ; les espaces réservés VIDEO/WIDTH/HEIGHT/SEED sont aussi acceptés ; les favoris ici sont indépendants de la carte vidéo ; comptes et clés .cn et .ai ne sont pas interchangeables",
"🧩 组 clip 与超分方法": "🧩 Clips de groupe et méthode d'upscale",
