"到黑即静音": "Silence au noir",
"声音随画面淡出": "le son fond avec l’image",
"停留": "maintien",
"集尾": "Fin d’épisode",
"本集覆盖": "remplacé pour cet épisode",
"按下方「集尾收束」": "voir « Fin d’épisode » ci-dessous",
"集尾淡出时长需在 0.3–3 秒之间": "Le fondu de fin doit durer 0,3–3 s",
"集尾停留需在 0–3 秒之间": "Le maintien de fin doit durer 0–3 s",
"切黑须停留 >0 秒(否则等于停在末帧)": "La coupe au noir exige un maintien > 0 s (sinon on s’arrête simplement sur la dernière image)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "Comment l’épisode se termine : le dernier groupe fond au noir/blanc puis maintient, ou coupe directement au noir (noir soudain pour le suspense ; le son se coupe au même instant par défaut) ; la piste audio externe fond/coupe au même moment et le générique de fin suit le maintien. Appliqué par render_transitions au rendu final ; un épisode peut le remplacer dans la barre de résumé des transitions de la page storyboard.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "Comment l’épisode se termine : le dernier groupe fond/coupe au noir puis maintient ; la piste audio externe fond ou coupe au même moment ; le générique de fin suit le maintien",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "Fin de cet épisode (remplacement par épisode ; défaut du projet dans « Rythme vidéo ») ; appliquée au rendu final, un montage existant doit relancer les transitions",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "Rendre l’aperçu de fin : 2 dernières secondes du dernier groupe + fin, même chaîne de filtres que le montage final",
// NSFW 模式(设置→高级;index.html 弹窗 + preview_storyboard.html 组卡 🔞)
"NSFW 模式": "Mode NSFW",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "Mode NSFW : désactivé par défaut ; une fois activé, vous pouvez définir un modèle de secours distinct pour le langage, l’image et la vidéo ; les tickets et groupes marqués NSFW basculent automatiquement vers les modèles de secours, et si le fournisseur principal rejette le contenu à la modération, il bascule et resoumet une fois",
"🔞 NSFW 模式": "🔞 Mode NSFW",
"启用 NSFW 模式": "Activer le mode NSFW",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "Désactivé par défaut. Une fois activé, vous pouvez définir un « modèle de secours » pour chacun des trois types ; l’assignation et la génération d’images/vidéos décident quand utiliser le secours selon trois niveaux : ① marque explicite d’abord — un ticket portant nsfw: true (le Producer déduit le nsfw du groupe à partir des content_flags des événements du découpage du scénario, ou vous le marquez manuellement avec 🔞 sur la carte du groupe dans l’aperçu du storyboard) part sur le modèle de secours dès la première assignation ; ② filet de sécurité — lorsque le fournisseur principal renvoie un rejet de modération de contenu, genmedia resoumet une fois au fournisseur de secours dans le même appel (non compté comme une relance) et marque le groupe NSFW pour ne plus tenter d’abord le modèle principal ; un modèle de langage rejeté n’est pas basculé en cours de processus : le modèle de langage de secours est utilisé lors de la réassignation du même task_id. Ce mode ne décide que du jeu de modèles utilisé ; il n’assouplit ni la revue de sécurité du contenu ni la classification des plateformes.",
"图像模型": "Modèle d’image",
"渠道须已在「🎨 生成模型」页配好 Key(未配置的置灰);留「不设置」= 该类不切换,照常走主模型。ComfyUI 的二级选项是运行方式。备用渠道不可用时不会偷跑主模型,而是报错交你裁决。": "Le fournisseur doit déjà avoir sa Key configurée sur la page « 🎨 Modèles de génération » (les non configurés sont grisés) ; laisser « Non défini » = ce type ne bascule pas et continue sur le modèle principal. Pour ComfyUI, l’option de second niveau est le mode d’exécution. Si le fournisseur de secours est indisponible, le modèle principal n’est pas exécuté en douce : une erreur est remontée pour que vous tranchiez.",
