"声延续": "Prolongation son (L-cut)",
"底床": "Lit sonore",
"画外台词": "Réplique hors champ",
"声桥": "Pont sonore",
"应用声桥": "Appliquer le pont sonore",
"声桥只配无插入段/无黑场的硬切或叠化": "Le pont sonore ne convient qu'aux coupes franches ou fondus enchaînés sans insert ni noir",
"需声画分离开启且切点旁有画外句": "Nécessite la séparation son/image activée et une réplique hors champ près de la coupe",
"把声桥写进本边界的设计(decide action=design),机检 transition_sound_bridge_valid": "Écrit le pont sonore dans le design de cette frontière (decide action=design) ; vérification transition_sound_bridge_valid",
"声桥时长需在 0.1–1.5 秒之间": "La durée du pont sonore doit être entre 0.1 et 1.5 s",
"声桥默认时长需在 0.1–1.5 秒之间": "La durée par défaut du pont sonore doit être entre 0.1 et 1.5 s",
"组边界的声桥(J/L-cut)默认值:声先入 = 下组声音提前压在本组尾画面上;声延续 = 本组声音拖过切点压在下组首画面上。承载「底床」= 只用去人声后的环境声预滚/延续,画面与口型不动;「画外台词」= 让切点旁的画外句跨切点,需声画分离开启且切点旁有画外句。电影感模式自动给建议,自定义模式按「边界处理」里的声先入/声延续出,极简模式不出;每处可在分镜预览页过场卡改": "Valeur par défaut des ponts sonores entre groupes (J/L-cut) : avance = le son du groupe suivant entre en avance sur la fin d'image de ce groupe ; prolongation = le son de ce groupe continue après la coupe sur la première image du suivant. « Lit sonore » = seule l'ambiance sans voix est anticipée/prolongée, image et lèvres intactes ; « réplique hors champ » = une réplique hors champ près de la coupe la traverse, nécessite la séparation activée et cette réplique. Le mode cinéma propose automatiquement, le mode personnalisé suit le choix du « traitement des frontières », le minimal n'en met pas ; chaque frontière se modifie sur la carte de transition du storyboard",
"音先入": "Son en avance (J-cut)",

