"关键词,如 veo / kling / flux;留空列出热门模型": "Mot-clé, p. ex. veo / kling / flux ; laisser vide pour les modèles populaires",
"正在搜索 Fal 模型目录…": "Recherche dans le catalogue de modèles Fal…",
"找到 {n} 个模型,点「选用」填入上面的模型栏": "{n} modèles trouvés ; cliquez sur « Utiliser » pour remplir le champ modèle ci-dessus",
"没有找到匹配的模型": "Aucun modèle correspondant",
"选用": "Utiliser",
"已内置适配": "Prise en charge intégrée",
"按参数表自动适配": "Adapté automatiquement aux paramètres",
"搜索 Fal 模型目录失败": "Échec de la recherche dans le catalogue Fal",
"已填入 {id},点「保存设置」后生效": "{id} renseigné ; cliquez sur « Enregistrer les paramètres » pour appliquer",
"搜到的模型不在上面清单里时,系统按该端点的参数表组请求:时长、分辨率、画幅取它支持的最接近值,不支持的输入(如尾帧、参考图)会直接报错;这些模型尚未逐个实测。": "Si un modèle trouvé n'est pas dans la liste ci-dessus, la requête est construite d'après la liste de paramètres de ce point d'accès : durée, résolution et format prennent la valeur prise en charge la plus proche, et les entrées non prises en charge (image de fin, images de référence…) provoquent une erreur. Ces modèles n'ont pas été testés un par un.",
"📡 发布渠道": "📡 Canaux de publication",
"已选 {n} 个渠道": "{n} canal(aux) sélectionné(s)",
"未选渠道:只出母版一份,不做分平台发布": "Aucun canal sélectionné : seul le master est produit, pas de publication par plateforme",
"勾选的渠道决定发布阶段的平台清单(封面 / 字幕 / 画幅矩阵 / 发布包);点「发布」把本集派给发布执行 Agent,按该渠道技能在本机 Chrome 里填好草稿并截图给你核对,最后一步「发布」由你亲手点": "Les canaux cochés forment la liste des plateformes de l'étape de publication (vignette / sous-titres / matrice de formats / paquet). « Publier » envoie cet épisode à l'agent de publication, qui remplit le brouillon dans votre Chrome local avec la compétence du canal et vous l'envoie en capture ; le dernier « Publier » reste à vous",
"没有可用的发布渠道": "Aucun canal de publication disponible",
"已派单给发布执行 Agent,运行中…(run {id})": "Envoyé à l'agent de publication, en cours… (run {id})",
"发布包已就绪": "Paquet de publication prêt",
"尚无发布包(将按母版成片直接上传)": "Pas encore de paquet (le master sera envoyé tel quel)",
"把 {ep} 的发布工单派给发布执行 Agent(渠道:{name});未勾选的渠道会同时勾上": "Envoyer l'ordre de publication de {ep} à l'agent de publication (canal : {name}) ; un canal non coché sera coché",
"该集还没有 final 成片,不能发布": "Cet épisode n'a pas encore de montage final, publication impossible",
"发布到 {name}": "Publier sur {name}",
"发布渠道": "Canaux de publication",
"画幅约束分镜构图/关键帧/视频/成片;发布渠道在「成片发布」页按渠道勾选并发布,只决定发布阶段的平台清单(不同画幅平台由发布期裁切适配);语言约束剧本/台词/旁白/字幕/配音;草稿分辨率用于迭代/待审版本,成片终稿由超分得到,分辨率越高视频生成费用越高": "Le format contraint composition du storyboard/images clés/vidéo/montage final ; les canaux de publication se cochent et se publient canal par canal sur la page Publication finale et ne déterminent que la liste des plateformes à l'étape de publication (les plateformes d'un autre format sont adaptées par recadrage) ; la langue contraint scénario/dialogues/narration/sous-titres/doublage ; la résolution de brouillon sert aux itérations/revues, le montage final est obtenu par upscaling, et plus la résolution est élevée plus la génération coûte",
"画幅约束画幅规范/分镜构图/关键帧/视频/成片;发布渠道在「成片发布」页勾选(可多选,也可不选),只决定发布阶段发到哪些平台及封面/字幕/画幅矩阵的平台清单,": "Le format contraint normes de cadrage/composition du storyboard/images clés/vidéo/montage final ; les canaux de publication se cochent sur la page Publication finale (multi-sélection, facultatif) et ne déterminent que les plateformes de publication et la liste des plateformes pour vignette/sous-titres/matrice de formats,",
"草稿已填好,待人工提交": "Brouillon rempli, en attente de votre envoi",
"已由人工提交": "Envoyé manuellement",
"发布成功": "Publié",
"发布失败": "Échec de la publication",
"片头内容": "Contenu du générique de début",
"片尾内容": "Contenu du générique de fin",
"未填写内容,由系统自行发挥": "Aucun contenu fourni — le système improvise",
"可留空:留空则由系统按项目风格自行发挥。署名、网址、版权声明等文字会原样呈现;引用 refs/ 下的素材(厂标 / Logo / 二维码)请写明路径。": "Facultatif : laissez vide et le système improvise selon le style du projet. Signatures, URL et mentions de copyright sont affichées telles quelles ; indiquez le chemin pour les ressources sous refs/ (logo studio / logo / QR code).",
"例如:3 秒内出剧名「XXX」,水墨晕开,配一声古琴;左下角挂 refs/logo.png": "ex. : titre « XXX » en 3 s, encre qui se diffuse, une note de guqin ; refs/logo.png en bas à gauche",
"例如:滚动演职员表,结尾停在「感谢观看 · 关注不迷路」,右下角放 refs/qrcode.png": "ex. : générique déroulant, fin sur « Merci d’avoir regardé · Abonnez-vous », refs/qrcode.png en bas à droite",
"可点右上角「+」附参考图(本机图片,不上传)": "+ (en haut à droite) pour joindre des références",
"对这张背景图提修改意见,直接发给分镜背景图 Agent:以这张图为参考(可附参考图)按意见新出一张,替换引用它的分镜,原图不动": "Envoyer des remarques sur ce fond directement à l’agent des fonds de plan : une nouvelle image est générée à partir de celle-ci (images de référence facultatives) et remplace celle-ci dans les plans qui l’utilisent ; l’original reste intact",
"分镜背景图 {key}(场景 {scene};文件 {file};{used};修订命令 python code/revise_shot_plate.py --project {proj} --scene {scene} --key {key} --change \"<英文修改要求>\" --note \"<用户原话>\" [--ref <参考图路径>]:以这张图为参考按意见新出一张入库,并替换引用它的分镜(用户点名只换某些镜时加 --only),原图不动;消息末尾附件里的图片逐张用 --ref 传入)": "Fond de plan {key} (scène {scene} ; fichier {file} ; {used} ; commande de révision python code/revise_shot_plate.py --project {proj} --scene {scene} --key {key} --change \"<modification en anglais>\" --note \"<propos de l’utilisateur>\" [--ref <chemin de l’image de référence>] : génère une nouvelle image à partir de celle-ci selon la remarque, l’ajoute à la bibliothèque et la substitue dans les plans qui l’utilisent (ajouter --only si l’utilisateur nomme des plans précis) ; l’original reste intact ; passer chaque image jointe en fin de message avec --ref)",
"开": "Activé",
"稀疏": "Clairsemé",
"适中": "Modéré",
"热闹": "Animé",
