"分镜未按此设定": "Storyboard pas à jour pour ce réglage",
"NPC 参与构图": "PNJ dans la composition",
"总开关已关闭:在「输出设置 → NPC 参与构图」里改为「按场次判定」后才能逐场开关": "L'interrupteur général est coupé : passez « Réglages de sortie → PNJ dans la composition » sur « Par scène » pour régler chaque scène",
"点击切换本场 NPC 参与构图(自动 / 开 / 关 + 密度)": "Cliquer pour changer les PNJ dans la composition de cette scène (Auto / Activé / Désactivé + densité)",
"在画面里加入路人、前景物体等 NPC 元素,补充空间、丰富层次,让场景有前中后三层": "Ajoute des éléments PNJ comme des passants et des objets au premier plan pour remplir l'espace et créer de la profondeur : premier plan, plan moyen et arrière-plan",
"自动判定:{v}": "Évaluation auto : {v}",
"自动判定:未判定(按关处理)": "Évaluation auto : non évaluée (traitée comme désactivée)",
"关键词建议:{v}": "Suggestion par mots-clés : {v}",
"跟随自动判定": "Suivre l'évaluation auto",
"改动不会自动重做已出的分镜:故事板页会标出未按新设定的场次,用该场「✏️ 修改」让分镜师补写": "Le changement ne refait pas les storyboards existants : la page storyboard signale les scènes non conformes au nouveau réglage ; utilisez « ✏️ Réviser » sur cette scène pour que le storyboardeur complète",
"前景层": "Premier plan",
"中景层": "Plan moyen",
"背景层": "Arrière-plan",
"按场次判定(默认)": "Par scène (par défaut)",
"全部关闭": "Tout désactivé",
"在画面里加入路人、前景物体等 NPC 元素补充空间,让场景有前中后三层。按场次判定=剧本拆解时逐场自动判断是否开启与密度(稀疏/适中/热闹),可在剧本预览页或故事板页按场次改为开或关;全部关闭=所有场次都不加。剧本里点名的群演不受影响": "Ajoute des éléments PNJ comme des passants et des objets au premier plan pour remplir l'espace et donner aux scènes un premier plan, un plan moyen et un arrière-plan. Par scène = le découpage du script évalue pour chaque scène s'il faut l'activer et avec quelle densité (clairsemé / modéré / animé) ; vous pouvez activer ou désactiver chaque scène dans l'aperçu du script ou la page storyboard. Tout désactivé = aucune scène n'en a. Les figurants nommés dans le script ne sont pas concernés",
"在终端中安装": "Installer dans un terminal",
"一键安装": "Installer en un clic",
"弹出终端窗口运行同一条官方安装命令;安装脚本有提问(如需要先装 Node.js)时可在终端里回答": "Ouvre une fenêtre de terminal qui exécute la même commande d'installation officielle ; répondez-y si le script d'installation pose des questions (par ex. installer Node.js d'abord)",
