"点「一键安装」会在后台运行 {cli} 官方安装命令(通常几分钟,网速慢时更久):": "Cliquez sur « Installer en un clic » pour exécuter en arrière-plan la commande d'installation officielle de {cli} (quelques minutes en général, davantage avec une connexion lente) :",
"请在本机终端运行官方安装命令:": "Exécutez la commande d'installation officielle dans un terminal de cet ordinateur :",
