"{cli} 已安装,但还没有登录账号,派单会失败。": "{cli} est installé mais n'est connecté à aucun compte, les tâches vont donc échouer.",
"点「登录」会打开一个终端窗口运行下面的命令,按提示在浏览器中用你自己的账号完成授权;完成后此窗口会自动检测。": "Cliquez sur « Se connecter » pour ouvrir une fenêtre de terminal qui exécute la commande ci-dessous, puis suivez les instructions pour autoriser avec votre propre compte dans le navigateur. Cette fenêtre vérifiera automatiquement une fois terminé.",
"请在本机终端运行下面的命令完成登录,然后点「重新检测」。": "Exécutez la commande ci-dessous dans un terminal de cet ordinateur pour vous connecter, puis cliquez sur « Revérifier ».",
