"当前系统不支持一键安装,请按官方安装指引手动安装": "L'installation en un clic n'est pas prise en charge sur ce système ; installez manuellement en suivant le guide officiel",
"无法访问官方安装地址:可能是所在地区不在该服务的支持范围内(如 Claude Code 仅在 Anthropic 支持的国家和地区提供),可换用其他引擎。": "Impossible d'accéder à l'adresse d'installation officielle : votre région n'est peut-être pas couverte par ce service (par exemple, Claude Code n'est proposé que dans les pays et régions pris en charge par Anthropic). Vous pouvez passer à un autre moteur.",
"无法连接官方下载地址,请检查网络或代理(设置 → 高级 → 网络检测 可查看命令行环境能否访问)。": "Impossible de se connecter à l'adresse de téléchargement officielle ; vérifiez le réseau ou le proxy (Réglages → Avancé → Diagnostic réseau indique si l'environnement en ligne de commande y accède).",
"需要 Node.js 22.19 或更新版本:点「在终端中安装」,安装脚本会询问是否代为安装 Node.js;也可先到 nodejs.org 安装。": "Nécessite Node.js 22.19 ou plus récent : cliquez sur « Installer dans un terminal » et le script d'installation proposera d'installer Node.js pour vous, ou installez-le d'abord depuis nodejs.org.",
